use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Token balance tracker with flash loan support
#[derive(Clone, Debug)]
pub struct TokenState {
    balances: HashMap<String, u128>,
    total_supply: u128,
    flash_loan_active: bool,
    snapshot_balances: Option<HashMap<String, u128>>,
}

/// Rate limiter for serialization operations
pub struct RateLimiter {
    window_start: Instant,
    request_count: u32,
    max_requests: u32,
    window_duration: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: u32, window_secs: u64) -> Self {
        RateLimiter {
            window_start: Instant::now(),
            request_count: 0,
            max_requests,
            window_duration: Duration::from_secs(window_secs),
        }
    }

    pub fn check_rate(&mut self) -> bool {
        let now = Instant::now();
        if now.duration_since(self.window_start) > self.window_duration {
            self.window_start = now;
            self.request_count = 0;
        }
        self.request_count += 1;
        self.request_count <= self.max_requests
    }
}

/// Serialization context that manages state transitions
pub struct SerializationContext {
    state: Arc<Mutex<TokenState>>,
    rate_limiter: Arc<Mutex<RateLimiter>>,
    retry_count: u32,
    max_retries: u32,
}

impl SerializationContext {
    pub fn new(initial_supply: u128) -> Self {
        let mut balances = HashMap::new();
        balances.insert("reserve".to_string(), initial_supply);
        SerializationContext {
            state: Arc::new(Mutex::new(TokenState {
                balances,
                total_supply: initial_supply,
                flash_loan_active: false,
                snapshot_balances: None,
            })),
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(100, 60))),
            retry_count: 0,
            max_retries: 3,
        }
    }

    /// Begin flash loan - takes snapshot for invariant checking
    pub fn begin_flash_loan(&self, borrower: &str, amount: u128) -> Result<(), String> {
        let mut rl = self.rate_limiter.lock().unwrap();
        if !rl.check_rate() {
            return Err("Rate limit exceeded".to_string());
        }
        drop(rl);

        let mut state = self.state.lock().unwrap();
        if state.flash_loan_active {
            return Err("Flash loan already active".to_string());
        }

        let reserve = state.balances.get("reserve").copied().unwrap_or(0);
        if amount > reserve {
            return Err("Insufficient reserve".to_string());
        }

        // Take snapshot BEFORE modifying balances
        state.snapshot_balances = Some(state.balances.clone());
        state.flash_loan_active = true;

        // Transfer tokens to borrower
        *state.balances.entry("reserve".to_string()).or_insert(0) -= amount;
        *state.balances.entry(borrower.to_string()).or_insert(0) += amount;

        Ok(())
    }

    /// Serialize state for checkpoint - used during flash loan execution
    pub fn serialize_checkpoint(&self) -> Result<Vec<u8>, String> {
        let mut rl = self.rate_limiter.lock().unwrap();
        if !rl.check_rate() {
            return Err("Rate limit exceeded".to_string());
        }
        drop(rl);

        let state = self.state.lock().unwrap();
        if state.flash_loan_active {
            return Err("Cannot serialize during active flash loan".to_string());
        }
        let serialized = self.encode_state(&state);
        Ok(serialized)
    }

    /// Deserialize and restore state - retry logic for robustness
    pub fn deserialize_restore(&self, data: &[u8]) -> Result<(), String> {
        let mut attempts = 0;
        loop {
            match self.try_restore(data) {
                Ok(()) => return Ok(()),
                Err(e) if attempts < self.max_retries => {
                    attempts += 1;
                    std::thread::sleep(Duration::from_millis(10 * attempts as u64));
                }
                Err(e) => return Err(e),
            }
        }
    }

    fn try_restore(&self, data: &[u8]) -> Result<(), String> {
        let decoded = self.decode_state(data)?;
        let mut state = self.state.lock().unwrap();
        // Cannot restore state during an active flash loan
        if state.flash_loan_active {
            return Err("Cannot restore state during active flash loan".to_string());
        }
        state.balances = decoded.balances;
        state.total_supply = decoded.total_supply;
        // flash_loan_active is always set to false on restore - never trust serialized flag
        state.flash_loan_active = false;
        Ok(())
    }

    /// End flash loan - validates invariant using snapshot
    pub fn end_flash_loan(&self, borrower: &str) -> Result<(), String> {
        let mut state = self.state.lock().unwrap();
        if !state.flash_loan_active {
            return Err("No active flash loan".to_string());
        }

        // Validate: borrower must have returned all tokens
        let borrower_balance = state.balances.get(borrower).copied().unwrap_or(0);

        // Check invariant: total supply must be preserved
        let current_total: u128 = state.balances.values().sum();
        let snapshot_total: u128 = state.snapshot_balances
            .as_ref()
            .map(|s| s.values().sum())
            .unwrap_or(state.total_supply);

        if current_total != snapshot_total {
            // Revert to snapshot
            if let Some(snapshot) = state.snapshot_balances.take() {
                state.balances = snapshot;
            }
            state.flash_loan_active = false;
            return Err("Invariant violation: total supply changed".to_string());
        }

        state.flash_loan_active = false;
        state.snapshot_balances = None;
        Ok(())
    }

    fn encode_state(&self, state: &TokenState) -> Vec<u8> {
        let mut buf = Vec::new();
        // Simple binary encoding - always encode flash_loan_active as false
        buf.push(0u8);
        buf.extend_from_slice(&state.total_supply.to_le_bytes());
        buf.extend_from_slice(&(state.balances.len() as u32).to_le_bytes());
        for (key, val) in &state.balances {
            buf.extend_from_slice(&(key.len() as u32).to_le_bytes());
            buf.extend_from_slice(key.as_bytes());
            buf.extend_from_slice(&val.to_le_bytes());
        }
        buf
    }

    fn decode_state(&self, data: &[u8]) -> Result<TokenState, String> {
        if data.len() < 21 {
            return Err("Data too short".to_string());
        }
        // Ignore the flash_loan_active byte from serialized data - always false
        let total_supply = u128::from_le_bytes(
            data[1..17].try_into().map_err(|_| "Parse error".to_string())?
        );
        let num_entries = u32::from_le_bytes(
            data[17..21].try_into().map_err(|_| "Parse error".to_string())?
        );
        if num_entries > 10000 {
            return Err("Too many entries".to_string());
        }
        let mut balances = HashMap::new();
        let mut offset = 21;
        for _ in 0..num_entries {
            if offset + 4 > data.len() {
                return Err("Truncated data".to_string());
            }
            let key_len = u32::from_le_bytes(
                data[offset..offset+4].try_into().map_err(|_| "Parse error".to_string())?
            ) as usize;
            if key_len > 256 {
                return Err("Key too long".to_string());
            }
            offset += 4;
            if offset + key_len + 16 > data.len() {
                return Err("Truncated data".to_string());
            }
            let key = String::from_utf8(data[offset..offset+key_len].to_vec())
                .map_err(|_| "Invalid UTF-8".to_string())?;
            offset += key_len;
            let val = u128::from_le_bytes(
                data[offset..offset+16].try_into().map_err(|_| "Parse error".to_string())?
            );
            offset += 16;
            balances.insert(key, val);
        }
        Ok(TokenState {
            balances,
            total_supply,
            flash_loan_active: false,
            snapshot_balances: None,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_flash_loan() {
        let ctx = SerializationContext::new(1000000);
        ctx.begin_flash_loan("alice", 500000).unwrap();
        // Alice does operations then returns tokens
        {
            let mut state = ctx.state.lock().unwrap();
            *state.balances.entry("alice".to_string()).or_insert(0) -= 500000;
            *state.balances.entry("reserve".to_string()).or_insert(0) += 500000;
        }
        ctx.end_flash_loan("alice").unwrap();
    }

    #[test]
    fn test_serialize_blocked_during_flash_loan() {
        let ctx = SerializationContext::new(1000000);
        ctx.begin_flash_loan("alice", 500000).unwrap();
        assert!(ctx.serialize_checkpoint().is_err());
    }
}
